namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;
    private static readonly string[] SampleMessages =
    [
        "Your report is ready to download",
        "New comment on your post",
        "System maintenance scheduled for tonight",
        "You have a new follower",
        "Payment processed successfully",
        "Deployment completed",
        "New feature available: dark mode"
    ];

    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        // Simulate initial notifications
        var notifications = new List<NotificationItem>
        {
            new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.Now.AddMinutes(-30) },
            new() { Id = 2, Message = "Your profile setup is complete", Timestamp = DateTime.Now.AddMinutes(-15) },
            new() { Id = 3, Message = "You have 3 pending tasks", Timestamp = DateTime.Now.AddMinutes(-5) },
        };
        return Task.FromResult(notifications);
    }

    public Task<NotificationItem?> CheckForNewNotificationAsync()
    {
        // ~30% chance of a new notification each poll
        if (Random.Shared.Next(0, 10) < 3)
        {
            var message = SampleMessages[Random.Shared.Next(SampleMessages.Length)];
            var notification = new NotificationItem
            {
                Id = Interlocked.Increment(ref _nextId),
                Message = message,
                Timestamp = DateTime.Now
            };
            return Task.FromResult<NotificationItem?>(notification);
        }
        return Task.FromResult<NotificationItem?>(null);
    }
}

